import{_ as o,H as a,f as t,i as l}from"./chunks/framework.DLd0CbzH.js";const h=JSON.parse('{"title":"ADR-001: Эталонный каталог приходит из TcenZor, а не строится внутри","description":"","frontmatter":{"type":"adr","status":"accepted","tags":["agelto","adr","catalog","matching","integration","tcenzor"],"created":"2026-06-13T00:00:00.000Z"},"headers":[],"relativePath":"03_Dev/ADR/ADR-001_Catalog_From_TcenZor.md","filePath":"03_Dev/ADR/ADR-001_Catalog_From_TcenZor.md"}'),r={name:"03_Dev/ADR/ADR-001_Catalog_From_TcenZor.md"};function i(n,e,c,s,g,d){return a(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="adr-001-эталонныи-каталог-приходит-из-tcenzor-а-не-строится-внутри" tabindex="-1">ADR-001: Эталонный каталог приходит из TcenZor, а не строится внутри <a class="header-anchor" href="#adr-001-эталонныи-каталог-приходит-из-tcenzor-а-не-строится-внутри" aria-label="Permalink to &quot;ADR-001: Эталонный каталог приходит из TcenZor, а не строится внутри&quot;">​</a></h1><h2 id="статус" tabindex="-1">Статус <a class="header-anchor" href="#статус" aria-label="Permalink to &quot;Статус&quot;">​</a></h2><p>✅ Принято</p><h2 id="контекст" tabindex="-1">Контекст <a class="header-anchor" href="#контекст" aria-label="Permalink to &quot;Контекст&quot;">​</a></h2><p>Agelto матчит позиции смет ЕИС к товарам. Изначально предполагалось, что Agelto <strong>сам строит</strong> эталонный слой — «самообучающийся MDM на базе КТРУ/КСР» (заявлено как конкурентное преимущество в [[02_Competitive_Analysis]]). При этом:</p><ul><li>эталонный MDM в коде <strong>не реализован</strong> (см. [[Architecture_Agelto]] §7.3 — «SQL-проект, в коде нет ни таблиц, ни моделей, ни pgvector»);</li><li>параллельно проект [[TcenZor]] строит <strong>универсальный каталог-хаб</strong> с тем же слоем (разделы/категории/эталоны/алиасы/нормативка ГОСТ·ОКПД2·КТРУ) — см. [[ADR-006_Universal_Catalog_Scope]] (TcenZor);</li><li>оба проекта независимо изобретали один и тот же товарный граф.</li></ul><p>Решение владельца: <strong>эталонный каталог — зона TcenZor (хаб)</strong>, Agelto — потребитель строительного среза по API ([[Universal_Catalog_Architecture]]).</p><h2 id="рассмотренные-варианты" tabindex="-1">Рассмотренные варианты <a class="header-anchor" href="#рассмотренные-варианты" aria-label="Permalink to &quot;Рассмотренные варианты&quot;">​</a></h2><h3 id="вариант-a-agelto-строит-собственныи-mdm-исходныи-план" tabindex="-1">Вариант A: Agelto строит собственный MDM (исходный план) <a class="header-anchor" href="#вариант-a-agelto-строит-собственныи-mdm-исходныи-план" aria-label="Permalink to &quot;Вариант A: Agelto строит собственный MDM (исходный план)&quot;">​</a></h3><ul><li>Полный контроль над каталогом и нормативкой.</li><li>❌ Дублирование с каталогом TcenZor; дважды решается нормализация/алиасы/ нормативка; MDM так и не реализован — это чистый greenfield-долг.</li></ul><h3 id="вариант-b-каталог-из-tcenzor-по-api-✅" tabindex="-1">Вариант B: Каталог из TcenZor по API ✅ <a class="header-anchor" href="#вариант-b-каталог-из-tcenzor-по-api-✅" aria-label="Permalink to &quot;Вариант B: Каталог из TcenZor по API ✅&quot;">​</a></h3><ul><li>TcenZor отдаёт строительный срез (категории/эталоны/алиасы/нормативка).</li><li>Agelto хранит локальную реплику/кэш для матчинга смет (у него уже есть pgvector-инфраструктура и <code>client_collections</code>).</li><li>✅ Не дублируем товарное ядро; фокус Agelto — сметный матчинг и лиды.</li></ul><h2 id="решение" tabindex="-1">Решение <a class="header-anchor" href="#решение" aria-label="Permalink to &quot;Решение&quot;">​</a></h2><ol><li><strong>Эталонный референс-каталог строительных материалов</strong> (категории/эталоны/ алиасы/ГОСТ/ОКПД2/КТРУ) <strong>приходит из [[TcenZor]] по API</strong>. Agelto его не строит.</li><li>Agelto хранит <strong>локальную реплику/кэш</strong> строительного среза для матчинга (offline-replica как базовый режим; <code>POST /catalog/match</code> к TcenZor — опция для сложных/редких позиций). Режим — открытый под-вопрос [[Universal_Catalog_Architecture]].</li><li><strong><code>client_collections</code> остаются в Agelto</strong> — это прайс-листы конкретного клиента-поставщика, не эталон. Матчинг: позиция сметы → <strong>эталон TcenZor</strong> → позиция коллекции клиента → лид (раньше связывали позицию сметы напрямую с коллекцией; теперь через эталонный слой).</li><li><strong>Тендеры, сметы, позиции смет (<code>ord_*</code>), уведомления, CRM-лиды</strong> остаются «дома» в Agelto.</li></ol><h2 id="последствия" tabindex="-1">Последствия <a class="header-anchor" href="#последствия" aria-label="Permalink to &quot;Последствия&quot;">​</a></h2><ul><li>✅ Снимается greenfield-долг построения собственного MDM.</li><li>✅ Единый каталог в экосистеме; алиасы/нормативка ведутся один раз в TcenZor.</li><li>✅ Фокус Agelto сужается до сильной стороны — парсинг смет + матчинг + лиды.</li><li>⚠️ <strong>Смена нарратива конкурентного преимущества.</strong> Барьер входа больше не «владение самообучающимся MDM», а: (1) качество <strong>сметного матчинга</strong> (парсинг неструктурированных PDF/Excel ЕИС), (2) накопленный <strong>golden dataset вердиктов</strong> верификации, (3) глубина строительной доменной экспертизы. Это требует правки [[02_Competitive_Analysis]] (см. [[Dev_Status]]).</li><li>⚠️ <strong>Внешняя зависимость от TcenZor</strong> как поставщика каталога: нужен SLA, версионирование среза, поведение при недоступности (работа по локальной реплике).</li><li>⚠️ Нормативка КТРУ/КСР как «эталон при матчинге» (BRD <code>F-MDM-*</code>) переезжает в потребление вместо построения — правка [[BRD (Agelto)]].</li></ul><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>[[Universal_Catalog_Architecture]] — контракт API TcenZor → Agelto</li><li>[[ADR-006_Universal_Catalog_Scope]] — расширение scope TcenZor (хаб)</li><li>[[Universal_Catalog_Model]] — модель данных каталога (TcenZor)</li><li>[[Architecture_Agelto]] §7, [[BRD (Agelto)]] §4.7 (F-MDM), [[02_Competitive_Analysis]] — затрагиваются</li></ul>',18)])])}const A=o(r,[["render",i]]);export{h as __pageData,A as default};
